32	func runArtifacts(args []string) error {
33		fs := flag.NewFlagSet("artifacts", flag.ContinueOnError)
34		root := fs.String("root", ".", "repository root containing anchored sources")
35		source := fs.String("source", "", "artifact authoring JSON")
36		out := fs.String("o", "-", "generated artifact catalog or - for stdout")
37		check := fs.Bool("check", false, "fail instead of writing when the output is stale")
38		if err := fs.Parse(args); err != nil {
39			if errors.Is(err, flag.ErrHelp) {
40				return err
41			}
42			return &artifactsUsageError{message: err.Error()}
43		}
44		if fs.NArg() != 0 || *source == "" {
45			return &artifactsUsageError{message: "usage: repoctx artifacts -source FILE [-root DIR] [-o FILE] [-check]"}
46		}
47		if *check && (*out == "" || *out == "-") {
48			return &artifactsUsageError{message: "artifacts -check requires a file passed with -o"}
49		}
50		authoring, err := readBounded(*source, 1<<20)
51		if err != nil {
52			return fmt.Errorf("read artifact authoring source: %w", err)
53		}
54		generated, err := artifacts.Generate(*root, authoring, artifacts.Limits{})
55		if err != nil {
56			return err
57		}
58		if !*check {
59			return writePayload(*out, generated)
60		}
61		current, err := os.ReadFile(*out)
62		if err != nil {
63			return fmt.Errorf("read generated artifact catalog: %w", err)
64		}
65		if !bytes.Equal(current, generated) {
66			return fmt.Errorf("generated artifact catalog is stale: run without -check")
67		}
68		return nil
69	}
