 86	// Compile validates artifact authoring, resolves its exact source anchors, and
 87	// returns both the canonical authoring declarations and derived catalog. It
 88	// performs no provider activation, authority resolution, or command execution.
 89	func Compile(root string, data []byte, limits Limits, permit PathPermit) (*Compilation, error) {
 90		doc, normalized, err := decodeAuthoring(data, limits)
 91		if err != nil {
 92			return nil, err
 93		}
 94		anchors, err := validateAuthoring(doc, normalized)
 95		if err != nil {
 96			return nil, err
 97		}
 98		catalog, err := authoringCatalog(doc, anchors, placeholderSpan)
 99		if err != nil {
100			return nil, err
101		}
102		if err := validateGenerated(catalog, normalized); err != nil {
103			return nil, err
104		}
105	
106		sources, err := sourceroot.Open(root)
107		if err != nil {
108			return nil, fmt.Errorf("open source root: %w", err)
109		}
110		defer sources.Close()
111		cache := make(map[string][]byte)
112		resolved := make(map[string]Span, len(doc.SourceAnchors))
113		for _, anchor := range doc.SourceAnchors {
114			if permit != nil && !permit(anchor.Path) {
115				return nil, fmt.Errorf("source anchor %q: path is outside caller scope", anchor.ID)
116			}
117			content, ok := cache[anchor.Path]
118			if !ok {
119				content, err = sources.Read(anchor.Path, 2<<20)
120				if err != nil {
121					return nil, fmt.Errorf("source anchor %q: read source %q: %w", anchor.ID, anchor.Path, err)
122				}
123				if !utf8.Valid(content) {
124					return nil, fmt.Errorf("source anchor %q: source %q is not UTF-8", anchor.ID, anchor.Path)
125				}
126				cache[anchor.Path] = content
127			}
128			span, resolveErr := resolveAnchor(content, anchor)
129			if resolveErr != nil {
130				return nil, fmt.Errorf("source anchor %q: %w", anchor.ID, resolveErr)
131			}
132			resolved[anchor.ID] = span
133		}
134		catalog, err = authoringCatalog(doc, anchors, func(anchor NamedSourceAnchor) Span {
135			return resolved[anchor.ID]
136		})
137		if err != nil {
138			return nil, err
139		}
140		if err := validateGenerated(catalog, normalized); err != nil {
141			return nil, err
142		}
143		return &Compilation{Authoring: doc, Catalog: catalog}, nil
144	}
