 89	// Atomically replace files after the complete bundle passes budget checks. A
 90	// failure before rename never replaces a previously valid output. Explicit
 91	// output paths are controlled by the caller, not inferred from repository text.
 92	func writePayload(path string, b []byte) error {
 93		if path == "" || path == "-" {
 94			_, e := os.Stdout.Write(b)
 95			return e
 96		}
 97		f, e := os.CreateTemp(filepath.Dir(path), ".repoctx-context-*")
 98		if e != nil {
 99			return e
100		}
101		temp := f.Name()
102		defer os.Remove(temp)
103		if _, e = f.Write(b); e != nil {
104			f.Close()
105			return e
106		}
107		if e = f.Sync(); e != nil {
108			f.Close()
109			return e
110		}
111		if e = f.Close(); e != nil {
112			return e
113		}
114		return os.Rename(temp, path)
115	}

